<?php $editing=isset($item['id']); ?><?php if(!empty($error)):?><div class="flash error"><?= e($error) ?></div><?php endif;?><form method="post" action="<?= $editing?'/admin/users/'.(int)$item['id']:'/admin/users' ?>"><?= csrf_field() ?><div class="settings-grid"><section class="panel"><div class="field"><label>Name</label><input name="name" value="<?= e($item['name']??'') ?>" required></div><div class="field"><label>Email</label><input name="email" type="email" value="<?= e($item['email']??'') ?>" required></div><div class="field"><label>Password <?= $editing?'<small>(leave blank to keep current)</small>':'' ?></label><input name="password" type="password" <?= $editing?'':'required' ?> autocomplete="new-password"></div><div class="field"><label>Bio</label><textarea class="short" name="bio"><?= e($item['bio']??'') ?></textarea></div></section><section class="panel"><div class="field"><label>Role</label><select name="role"><option value="administrator"<?= selected($item['role']??'author','administrator') ?>>Administrator</option><option value="editor"<?= selected($item['role']??'author','editor') ?>>Editor</option><option value="author"<?= selected($item['role']??'author','author') ?>>Author</option></select><small>Administrators control the site. Editors manage content. Authors manage their own posts.</small></div><div class="field"><label>Status</label><select name="status"><option value="active"<?= selected($item['status']??'active','active') ?>>Active</option><option value="disabled"<?= selected($item['status']??'active','disabled') ?>>Disabled</option></select></div></section></div><div class="form-footer"><button class="btn primary" type="submit">Save user</button><a class="btn ghost" href="/admin/users">Cancel</a></div></form>